  "test_path": "tests/unit/test_observe_description.py",
  "test": "import pytest

from langfuse import observe


def test_capture_description_attribute(langfuse_memory_client: any, memory_exporter: any) -> None:
    @observe(name="test_desc", capture_description=True)
    def foo() -> int:
        """Sample function description"""
        return 42

    assert foo() == 42

    # flush any pending spans to the exporter
    langfuse_memory_client.flush()

    spans = [s for s in memory_exporter.get_finished_spans() if s.name == "test_desc"]
    assert spans, "No span named 'test_desc' was recorded"
    span = spans[0]
    # The description attribute should match the function's docstring
    assert span.attributes.get("description") == "Sample function description"
